configFiles.piko-service.ps1:
param([ValidateSet('install','remove')][string]$Action,[string]$Root,[string]$Data)
$ErrorActionPreference='Stop'
$helper=Join-Path $Root 'FlClashHelperService.exe'
$marker=Join-Path $Data 'piko-flclash-service.json'
$service=Get-CimInstance Win32_Service -Filter "Name='FlClashHelperService'"
$owned=$false
if (Test-Path -LiteralPath $marker) {
 $record=Get-Content -LiteralPath $marker -Raw | ConvertFrom-Json
 if ($record.executable -ne $helper) {throw 'Service ownership record mismatch'}
 $owned=$true
}
if ($service) {
 if (!$owned -or !$service.PathName.StartsWith(('"'+$helper+'"'),[StringComparison]::OrdinalIgnoreCase) -and !$service.PathName.StartsWith(($helper+' '),[StringComparison]::OrdinalIgnoreCase)) {throw 'An external FlClashHelperService exists; remove it explicitly through its owner first'}
}
if ($Action -eq 'install') {
 if (!$owned) { @{executable=$helper;created=(Get-Date).ToUniversalTime().ToString('o')} | ConvertTo-Json | Set-Content -LiteralPath $marker -Encoding UTF8 }
 & $helper install --owner-pid $PID
 if ($LASTEXITCODE -ne 0) {throw "Helper service install failed: $LASTEXITCODE"}
} else {
 if (!$owned) {throw 'No owned FlClash service record'}
 if ($service) { & $helper uninstall; if ($LASTEXITCODE -ne 0) {throw "Helper service removal failed: $LASTEXITCODE"} }
 Remove-Item -LiteralPath $marker
}
